/// Source grammar shared by module inventory and imported StyleX definitions.
/// JavaScript accepts JSX (as React Native/Babel projects commonly do), but
/// TypeScript only does so in TSX. An omitted filename keeps the historical
/// TSX API; MDX integrations pass already generated JSX, not authored Markdown.
pub fn source_type_for_file(file: Option<&str>) -> SourceType {
    let source_type = file
        .and_then(|file| SourceType::from_path(file).ok())
        .unwrap_or_else(|| {
            SourceType::from_extension("tsx").expect("\"tsx\" is a known extension")
        });
    source_type.with_jsx(source_type.is_javascript())
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub struct ImportBinding {
    /// Module specifier as written, for example `react-native`.
    pub source: String,
    /// Exported name, or `default` / `*` for those import forms.
    pub imported: String,
    /// Binding visible to expressions and JSX in this module.
    pub local: String,
}

pub struct ParseOutput {
    /// Parser recovery is useful for inventory, but not proof that source parses.
    /// Keep these separate from target-independent semantic diagnostics.
    pub syntax_errors: Vec<ParseSyntaxError>,
    pub roots: Vec<Root>,
    /// Local bindings that occur as the root name of an actual JSX tag.
    ///
    /// Unlike a text scan, this excludes comments and TypeScript type
    /// arguments while retaining namespace JSX such as `Animated.View`.
    pub jsx_bindings: std::collections::HashSet<String>,
    /// Diagnostics about the source as written, independent of target
    /// platform -- backends raise their own separately during `lower()`.
    pub diagnostics: Vec<Diagnostic>,
    /// Source ranges the compiler read exactly and turned into scoped
    /// rules. The candidate scan subtracts these, so a class that already
    /// compiled away doesn't also ship under its Tailwind name.
    pub consumed_class_spans: Vec<hozo_ir::SourceSpan>,
    /// Source ranges that cannot contain a class name at all.
    ///
    /// A different subtraction from `consumed_class_spans`, and a stronger
    /// one: that list is what the compiler *did* read, this is what no
    /// program could ever read. A comment is not code, and JSX text is the
    /// string a person sees on the page -- neither has a path to
    /// `className` under any evaluation.
    ///
    /// The byte scan cannot tell prose from utilities, because it is a
    /// byte scan: Tailwind's own `oxide` has the same property, and a
    /// sentence about a table that will be visible behind a border yields
    /// `table`, `visible` and `border`. Hozo parses the file anyway, so it
    /// can afford to know better -- but only where the answer is certain.
    /// String literals stay in: an app's copy lives there, and so does
    /// every dynamically composed class name, which is the whole reason
    /// the scan exists.
    pub non_class_spans: Vec<hozo_ir::SourceSpan>,
    /// Runtime imports collected from the same module record as `roots`.
    /// Backends use these instead of parsing the source again to rediscover
    /// bindings the parser has already resolved.
    pub imports: Vec<ImportBinding>,
    /// Primitive-named bindings deliberately carried rather than lowered.
    /// Kept because a backend may need to distinguish a carried foreign tag
    /// from one of Hozo's own primitives that unexpectedly survived.
    pub foreign_primitives: std::collections::HashSet<String>,
    /// Every class prop in the module, on any element, with the class lists
    /// the file spells out -- what `runtime_class_lists` returns, from this
    /// same parse (#1166).
    pub runtime_class_lists: Vec<RuntimeClassList>,
}

pub struct ParseSyntaxError {
    pub message: String,
    pub span: hozo_ir::SourceSpan,
}

fn import_bindings(module_record: &ModuleRecord<'_>) -> Vec<ImportBinding> {
    module_record
        .import_entries
        .iter()
        .filter(|entry| !entry.is_type)
        .map(|entry| ImportBinding {
            source: entry.module_request.name.to_string(),
            imported: match &entry.import_name {
                ImportImportName::Name(name) => name.name.to_string(),
                ImportImportName::NamespaceObject => "*".to_string(),
                ImportImportName::Default(_) => "default".to_string(),
            },
            local: entry.local_name.name.to_string(),
        })
        .collect()
}

fn parse_import_bindings(source_text: &str) -> Vec<ImportBinding> {
    let allocator = Allocator::default();
    let source_type = SourceType::from_extension("tsx").expect("\"tsx\" is a known extension");
    let ret = Parser::new(&allocator, source_text, source_type).parse();
    import_bindings(&ret.module_record)
}

/// Every binding a source file imports from one module, by local name.
///
/// Narrower than it looks: the Native backend needs it to avoid
/// re-declaring a binding the file already imported from `react-native`,
/// which is a SyntaxError rather than a duplicate.
pub fn module_imports(source_text: &str, module: &str) -> Vec<String> {
    parse_import_bindings(source_text)
        .into_iter()
        .filter(|entry| entry.source == module)
        .map(|entry| entry.local)
        .collect()
}

/// Names a *trusted* module exports that are not the primitive Hozo means.
///
/// One entry, and it matters: React Native's `Button` takes a `title` and
/// renders no children, while Hozo's is a semantic primitive that lowers to
/// a Pressable wrapping its children. Trusting `react-native` wholesale
/// turned an ordinary `<Button title="Go" onPress={f} />` into
/// `<Pressable accessibilityRole="button" onPress={f} title="Go"></Pressable>`
/// -- a control that renders nothing at all, in a file the author never
/// asked Hozo to change.
///
/// Every other name React Native and Hozo share -- `View`, `Text`,
/// `Image`, `ScrollView`, `FlatList`, `Pressable`, `TextInput` -- is the
/// same component, which is why the rest of `react-native` is trusted.
const INCOMPATIBLE_PRIMITIVES: &[(&str, &str)] = &[("react-native", "Button")];

/// Primitive-named bindings that must not be lowered: imported from a
/// module the project doesn't trust, or named on the incompatibility list.
pub fn foreign_primitives(
    source_text: &str,
    sources: &[String],
) -> std::collections::HashSet<String> {
    foreign_primitives_from_imports(&parse_import_bindings(source_text), sources)
}

fn foreign_primitives_from_imports(
    imports: &[ImportBinding],
    sources: &[String],
) -> std::collections::HashSet<String> {
    imports
        .iter()
        .filter(|entry| {
            jsx::is_primitive_name(&entry.local) || jsx::is_primitive_name(&entry.imported)
        })
        .filter(|entry| {
            let module = entry.source.as_str();
            let imported = entry.imported.as_str();
            !sources.iter().any(|s| s == module)
                || INCOMPATIBLE_PRIMITIVES.contains(&(module, imported))
        })
        .map(|entry| entry.local.clone())
        .collect()
}

fn primitive_aliases_from_imports(
    imports: &[ImportBinding],
    sources: Option<&[String]>,
) -> std::collections::HashMap<String, String> {
    imports
        .iter()
        .filter(|entry| {
            sources.is_none_or(|allowed| allowed.iter().any(|source| source == &entry.source))
        })
        .filter(|entry| jsx::is_primitive_name(&entry.imported))
        .filter(|entry| {
            !INCOMPATIBLE_PRIMITIVES.contains(&(entry.source.as_str(), entry.imported.as_str()))
        })
        .map(|entry| (entry.local.clone(), entry.imported.clone()))
        .collect()
}

fn animated_namespaces_from_imports(
    imports: &[ImportBinding],
    sources: Option<&[String]>,
) -> std::collections::HashSet<String> {
    imports
        .iter()
        .filter(|entry| entry.imported == "Animated")
        .filter(|entry| {
            sources.is_none_or(|allowed| allowed.iter().any(|source| source == &entry.source))
        })
        .map(|entry| entry.local.clone())
        .collect()
}

/// Parses TSX source into Hozo IR node trees, one per top-level JSX
/// element found (e.g. one per component's returned JSX).
pub fn parse_tsx(source_text: &str) -> ParseOutput {
    parse_tsx_with(source_text, None)
}

/// Exported static StyleX facts from one module, detached from its AST.
///
/// This remains useful independently of lowering: bundlers persist it to
/// decide which modules belong in the shared parsed-rule registry.
pub fn summarize_stylex_module(source_text: &str) -> StylexModuleSummary {
    summarize_stylex_module_for_file(source_text, None)
}

pub fn summarize_stylex_module_for_file(
    source_text: &str,
    file: Option<&str>,
) -> StylexModuleSummary {
    let allocator = Allocator::default();
    let source_type = source_type_for_file(file);
    let ret = Parser::new(&allocator, source_text, source_type).parse();
    let frontend = stylex::Frontend::collect(&ret.program, &ret.module_record);
    let mut summary = frontend.module_summary(&ret.program, &ret.module_record);
    summary.context = Some(stylex::context_summary(
        &ret.program,
        &ret.module_record,
        ret.diagnostics.is_empty(),
    ));
    summary
}

/// Parses TSX, lowering only primitives imported from `sources`.
///
/// `None` is the unconstrained low-level mode: it trusts every module and
/// retains the historical bare-name shorthand used by compact parser
/// fixtures. Supplying a source list requires a matching trusted import. That
/// distinction prevents an application's own same-file `function Text()`
/// from being mistaken for Hozo's `Text` merely because the names coincide.
///
/// The list is per *tag*, not per file. A real Expo app has
/// `<View className="p-4">` from `react-native` and `<Button label="Save">`
/// from `@expo/ui` in the same tree, and those names are the same names:
/// `@expo/ui` exports `Text`, `Button`, `List`, `ListItem`, `ScrollView`
/// and `TextInput`, every one a native platform component sharing nothing
/// with the Hozo primitive but its spelling. Refusing the whole file would
/// leave the half Hozo does understand uncompiled; lowering the whole file
/// would replace someone's SwiftUI button with a `<div>`. So a foreign tag
/// becomes `Child::Verbatim` -- carried, exactly like any other component
/// the compiler does not model -- and the tree around it compiles.
pub fn parse_tsx_with(source_text: &str, sources: Option<&[String]>) -> ParseOutput {
    parse_tsx_with_stylex(source_text, sources, None, &[])
}

/// Parses TSX with bundler-resolved, project-cached StyleX imports.
pub fn parse_tsx_with_stylex(
    source_text: &str,
    sources: Option<&[String]>,
    registry: Option<&StylexModuleRegistry>,
    bindings: &[StylexExternalBinding],
) -> ParseOutput {
    parse_module_for_file(source_text, sources, registry, bindings, None)
}

/// The filename selects grammar, not integration eligibility. Build adapters
/// still decide which files may have their JSX lowered.
pub fn parse_module_for_file(
    source_text: &str,
    sources: Option<&[String]>,
    registry: Option<&StylexModuleRegistry>,
    bindings: &[StylexExternalBinding],
    file: Option<&str>,
) -> ParseOutput {
    parse(
        source_text,
        sources,
        registry,
        bindings,
        ReactNativeCompat::Lower,
        file,
        ParseFeatures::default(),
    )
}

/// `parse_module_for_file`, with functions the project declares join
/// classes as `clsx` does (#964).
pub fn parse_module_for_file_with_helpers(
    source_text: &str,
    sources: Option<&[String]>,
    registry: Option<&StylexModuleRegistry>,
    bindings: &[StylexExternalBinding],
    file: Option<&str>,
    class_helpers: &[ClassHelper],
) -> ParseOutput {
    parse(
        source_text,
        sources,
        registry,
        bindings,
        ReactNativeCompat::Lower,
        file,
        ParseFeatures { class_helpers },
    )
}

/// The package whose components stand in for React Native's own on the Web.
const REACT_NATIVE_COMPAT_OWNER: &str = "@hozo/rn-compat";

/// Whether a React Native compatibility component may be lowered.
///
/// `TouchableOpacity`, `TouchableWithoutFeedback`, `ActivityIndicator`,
/// `Modal` and `Animated.View` have no DOM element to become. On the Web
/// they lower to a component from `@hozo/rn-compat`, and that import lands
/// in the application's source -- which, under strict pnpm, resolves only
/// if the application declared the package. An application that wrote
/// `import { Modal } from 'react-native'` and configured nothing declared
/// no such thing, and had no reason to expect its imports rewritten.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ReactNativeCompat {
    /// Wherever it was imported from. What the Native backend wants -- on
    /// device the component stays React Native's own and only its classes
    /// lower -- and what a Web project that opted into rewriting asked for.
    Lower,
    /// Only when imported from `@hozo/rn-compat` itself, which the author
    /// then declared. The same component from `react-native` is carried
    /// as written, for React Native Web to resolve.
    OnlyFromOwner,
}

/// Parses TSX for the Web backend, which decides whether React Native's
/// compatibility components lower. See [`ReactNativeCompat`].
pub fn parse_tsx_for_web(
    source_text: &str,
    sources: Option<&[String]>,
    registry: Option<&StylexModuleRegistry>,
    bindings: &[StylexExternalBinding],
    compat: ReactNativeCompat,
) -> ParseOutput {
    parse(
        source_text,
        sources,
        registry,
        bindings,
        compat,
        None,
        ParseFeatures::default(),
    )
}

/// `parse_tsx_for_web`, with functions the project declares join classes
/// as `clsx` does (#964).
pub fn parse_tsx_for_web_with_helpers(
    source_text: &str,
    sources: Option<&[String]>,
    registry: Option<&StylexModuleRegistry>,
    bindings: &[StylexExternalBinding],
    compat: ReactNativeCompat,
    class_helpers: &[ClassHelper],
) -> ParseOutput {
    parse(
        source_text,
        sources,
        registry,
        bindings,
        compat,
        None,
        ParseFeatures { class_helpers },
    )
}

/// Per-call optional analyses stay named and default-off.
#[derive(Default)]
struct ParseFeatures<'a> {
    class_helpers: &'a [ClassHelper],
}

fn parse(
    source_text: &str,
    sources: Option<&[String]>,
    registry: Option<&StylexModuleRegistry>,
    bindings: &[StylexExternalBinding],
    compat: ReactNativeCompat,
    file: Option<&str>,
    features: ParseFeatures<'_>,
) -> ParseOutput {
    let allocator = Allocator::default();
    let source_type = source_type_for_file(file);
    let ret = Parser::new(&allocator, source_text, source_type).parse();

    let imports = import_bindings(&ret.module_record);
    let mut foreign = match sources {
        None => std::collections::HashSet::new(),
        Some(sources) => foreign_primitives_from_imports(&imports, sources),
    };
    let primitive_aliases = primitive_aliases_from_imports(&imports, sources);
    let mut animated_namespaces = animated_namespaces_from_imports(&imports, sources);
    if compat == ReactNativeCompat::OnlyFromOwner {
        // Foreign rather than a separate list of refusals: a foreign tag is
        // already carried verbatim with the tree around it still compiled,
        // which is exactly the treatment wanted here.
        for entry in imports
            .iter()
            .filter(|entry| entry.source != REACT_NATIVE_COMPAT_OWNER)
        {
            if entry.imported == "Animated" {
                animated_namespaces.remove(&entry.local);
            } else if jsx::is_react_native_compat_name(&entry.imported) {
                foreign.insert(entry.local.clone());
            }
        }
    }
    let mut stylex = stylex::Frontend::collect(&ret.program, &ret.module_record);
    if let Some(registry) = registry {
        registry.attach(&mut stylex, &ret.module_record, bindings);
    }
    let stylex_scan_spans = stylex.scan_spans.clone();
    let helper_imports =
        dynamic_class::helper_import_offsets(&ret.module_record, features.class_helpers);
    let bindings_facts = rest::analyze_with_imports(&ret.program, &helper_imports);
    let runtime_class_lists = class_literals::collect_runtime_class_lists(
        &ret.program,
        source_text,
        &bindings_facts.constants,
    );
    let scope = jsx::Scope {
        rest_exclusions: &bindings_facts.rest,
        constants: &bindings_facts.constants,
        helper_import_refs: &bindings_facts.imports,
        module_record: &ret.module_record,
        class_helpers: features.class_helpers,
        tailwind_units: Default::default(),
        foreign: &foreign,
        primitive_aliases: &primitive_aliases,
        allow_unbound_primitives: sources.is_none(),
        animated_namespaces: &animated_namespaces,
        stylex,
    };

    let mut collector = JsxCollector::new(&scope);
    collector.visit_program(&ret.program);
    collector.consumed.extend(stylex_scan_spans);
    let units = std::mem::take(&mut *scope.tailwind_units.borrow_mut()).finish();
    for root in &mut collector.roots {
        root.tailwind_units = units.clone();
    }

    let mut jsx_bindings = JsxBindingCollector::default();
    jsx_bindings.visit_program(&ret.program);

    for root in &collector.roots {
        aria_check::check(&root.node, &mut collector.diagnostics);
    }
    important::diagnose(
        &collector.roots,
        &runtime_class_lists,
        &mut collector.diagnostics,
    );

    let mut non_class_spans: Vec<hozo_ir::SourceSpan> = ret
        .program
        .comments
        .iter()
        .map(|comment| hozo_ir::SourceSpan {
            start: comment.span.start,
            end: comment.span.end,
        })
        .collect();
    let mut text = JsxTextSpans { spans: Vec::new() };
    text.visit_program(&ret.program);
    non_class_spans.extend(text.spans);

    ParseOutput {
        syntax_errors: ret
            .diagnostics
            .iter()
            .map(|error| {
                let span = error.labels.first().map_or(
                    hozo_ir::SourceSpan { start: 0, end: 0 },
                    |label| hozo_ir::SourceSpan {
                        start: label.offset(),
                        end: label.offset() + label.len(),
                    },
                );
                ParseSyntaxError {
                    message: error.to_string(),
                    span,
                }
            })
            .collect(),
        roots: collector.roots,
        jsx_bindings: jsx_bindings.bindings,
        diagnostics: collector.diagnostics,
        consumed_class_spans: collector.consumed,
        non_class_spans,
        imports,
        foreign_primitives: foreign,
        runtime_class_lists,
    }
}

/// Collects the binding at the left edge of every JSX element name.
/// `Animated.View` therefore records `Animated`, while `<View>` records
/// `View`. Oxc has already separated JSX from comments and type syntax.
#[derive(Default)]
struct JsxBindingCollector {
    bindings: std::collections::HashSet<String>,
}

impl<'a> Visit<'a> for JsxBindingCollector {
    fn visit_jsx_element(&mut self, element: &oxc_ast::ast::JSXElement<'a>) {
        match &element.opening_element.name {
            oxc_ast::ast::JSXElementName::IdentifierReference(identifier) => {
                self.bindings.insert(identifier.name.to_string());
            }
            oxc_ast::ast::JSXElementName::MemberExpression(member) => {
                if let Some(identifier) = member.object.get_identifier() {
                    self.bindings.insert(identifier.name.to_string());
                }
            }
            oxc_ast::ast::JSXElementName::Identifier(_)
            | oxc_ast::ast::JSXElementName::NamespacedName(_)
            | oxc_ast::ast::JSXElementName::ThisExpression(_) => {}
        }
        oxc_ast_visit::walk::walk_jsx_element(self, element);
    }
}

/// The spans of every JSX text child, wherever it appears.
///
/// A separate walk from `JsxCollector` because that one is about Hozo's
/// primitives and this is about the whole file: `<div>a visible table</div>`
/// is prose the scan should not read, and the collector never descends
/// into an element it does not lower.
struct JsxTextSpans {
    spans: Vec<hozo_ir::SourceSpan>,
}

impl JsxTextSpans {
    /// Text children written as `{"..."}` rather than as bare JSX text.
    ///
    /// The same prose in the other spelling, and the spelling every MDX
    /// compiler emits: `@mdx-js/mdx` with `jsx: true` writes a paragraph
    /// as `<p>{"The block layout puts the table..."}</p>`, so subtracting
    /// `JSXText` alone left a documentation page contributing every
    /// English word that happens to be a utility.
    ///
    /// Child position is what makes this safe, and it is a different node
    /// from the attribute one: `className={"p-4"}` is a
    /// `JSXAttributeValue`, never a `JSXChild`, so it is untouched. A
    /// string literal standing alone as a child is rendered text and has
    /// no path to `className` under any evaluation -- the same claim
    /// `JSXText` makes, in the syntax a compiler produces rather than the
    /// one a person types.
    fn note_children(&mut self, children: &[oxc_ast::ast::JSXChild<'_>]) {
        for child in children {
            let oxc_ast::ast::JSXChild::ExpressionContainer(container) = child else {
                continue;
            };
            // Only a literal, and only when it is the whole expression.
            // `{cx('p-4')}` is a call this has no business reading.
            let oxc_ast::ast::JSXExpression::StringLiteral(literal) = &container.expression else {
                continue;
            };
            self.spans.push(hozo_ir::SourceSpan {
                start: literal.span.start,
                end: literal.span.end,
            });
        }
    }
}

impl<'a> Visit<'a> for JsxTextSpans {
    fn visit_jsx_text(&mut self, text: &oxc_ast::ast::JSXText<'a>) {
        self.spans.push(hozo_ir::SourceSpan {
            start: text.span.start,
            end: text.span.end,
        });
    }

    fn visit_jsx_element(&mut self, element: &oxc_ast::ast::JSXElement<'a>) {
        self.note_children(&element.children);
        oxc_ast_visit::walk::walk_jsx_element(self, element);
    }

    fn visit_jsx_fragment(&mut self, fragment: &oxc_ast::ast::JSXFragment<'a>) {
        self.note_children(&fragment.children);
        oxc_ast_visit::walk::walk_jsx_fragment(self, fragment);
    }
}

